presets.sampleData:
CREATE TABLE Users (
  id INT PRIMARY KEY,
  name VARCHAR(50),
  email VARCHAR(50) UNIQUE
);

CREATE TABLE Orders (
  id INT PRIMARY KEY,
  user_id INT REFERENCES Users(id),
  total DECIMAL(10,2)
);

CREATE TABLE Accounts (
  id INT PRIMARY KEY,
  balance DECIMAL(10,2),
  owner VARCHAR(50)
);

CREATE TABLE Transactions (
  id INT PRIMARY KEY,
  account_id INT REFERENCES Accounts(id),
  amount DECIMAL(10,2)
);

CREATE TABLE Roles (
  id INT PRIMARY KEY,
  name VARCHAR(50)
);

CREATE TABLE AdminUsers (
  id INT PRIMARY KEY,
  role_id INT REFERENCES Roles(id),
  username VARCHAR(50)
);

CREATE TABLE Products (
  sku VARCHAR(50) PRIMARY KEY,
  price DECIMAL(10,2),
  stock INT
);

CREATE TABLE Reviews (
  id INT PRIMARY KEY,
  product_sku VARCHAR(50) REFERENCES Products(sku),
  rating INT
);

model Profile {
  id     Int    @id
  bio    String
  userId Int
  user   User   @relation(fields: [userId], references: [id])
}

model User {
  id       Int       @id
  email    String
  profiles Profile[]
}

CREATE TABLE pg_users (
  usr_id INT PRIMARY KEY,
  usr_name VARCHAR(50)
);

CREATE TABLE pg_sessions (
  sid INT PRIMARY KEY,
  usr_id INT REFERENCES pg_users(usr_id),
  expires_at TIMESTAMP
);

CREATE TABLE my_categories (
  cat_id INT PRIMARY KEY,
  cat_title VARCHAR(50)
) ENGINE=InnoDB;

CREATE TABLE my_items (
  item_id INT PRIMARY KEY,
  cat_id INT REFERENCES my_categories(cat_id),
  item_name VARCHAR(50)
) ENGINE=InnoDB;

CREATE TABLE auth_users (
  id INT PRIMARY KEY,
  email VARCHAR(50)
);

CREATE TABLE public_profiles (
  id INT PRIMARY KEY,
  auth_id INT REFERENCES auth_users(id),
  display_name VARCHAR(50)
);

